import { createRoot } from "react-dom/client";
import { FrostyBlitzGame } from "./FrostyBlitzComponent";

const puzzleRootElem = document.getElementById("frosty-blitz-puzzle-root");
if (puzzleRootElem) {
  const root = createRoot(puzzleRootElem);
  root.render(<FrostyBlitzGame />);
} else {
  console.error(
    "Could not mount because #frosty-blitz-puzzle-root was nowhere to be found",
  );
}
