const generateMathProblem = (): MathProblem => {
  const operations = ["+", "-", "x", "÷"];
  const operation = operations[Math.floor(Math.random() * operations.length)];
  let num1: number, num2: number, correctAnswer: number, problem: string;

  switch (operation) {
    case "+":
      num1 = Math.floor(Math.random() * 20) + 2;
      num2 = Math.floor(Math.random() * 20) + 2;
      correctAnswer = num1 + num2;
      problem = `${num1} + ${num2} = ?`;
      break;
    case "-":
      num1 = Math.floor(Math.random() * 20) + 10;
      num2 = Math.floor(Math.random() * 10) + 2;
      correctAnswer = num1 - num2;
      problem = `${num1} - ${num2} = ?`;
      break;
    case "x":
      num1 = Math.floor(Math.random() * 9) + 2;
      num2 = Math.floor(Math.random() * 9) + 2;
      correctAnswer = num1 * num2;
      problem = `${num1} x ${num2} = ?`;
      break;
    case "÷": {
      num2 = Math.floor(Math.random() * 9) + 2; // Divisor
      const quotient = Math.floor(Math.random() * 9) + 2;
      num1 = num2 * quotient; // Ensure even division
      correctAnswer = quotient;
      problem = `${num1} ÷ ${num2} = ?`;
      break;
    }
    default:
      // Fallback to multiplication
      num1 = Math.floor(Math.random() * 9) + 2;
      num2 = Math.floor(Math.random() * 9) + 2;
      correctAnswer = num1 * num2;
      problem = `${num1} x ${num2} = ?`;
  }

  const options = new Set<number>([correctAnswer]);
  let attempts = 0;
  // Generate two unique incorrect answers (limited attempts)
  while (options.size < 3 && attempts < 50) {
    const offset = Math.floor(Math.random() * 10) - 5;
    const incorrect = correctAnswer + offset;
    if (incorrect !== correctAnswer && incorrect > 0) options.add(incorrect);
    attempts++;
  }
  // Fallback if random generation fails
  while (options.size < 3) {
    options.add(correctAnswer + options.size + 1);
  }

  const shuffled = Array.from(options).sort(() => Math.random() - 0.5);
  return {
    id: Date.now() + Math.random(),
    x: GAME_WIDTH,
    y: Math.floor(Math.random() * (GAME_HEIGHT / 3)) + 50,
    problem,
    correctAnswer,
    options: shuffled.map((v, i) => ({ key: ["Z", "X", "C"][i], value: v })),
    solved: false,
    opacity: 1,
  };
};

// Checks if a projectile trajectory would unfairly block the player
const isTrajectoryBlocked = (
  spawnX: number,
  spawnY: number,
  vy: number,
  buildings: Building[],
) => {
  const relativeSpeed = PSET_SPEED + BUILDING_SCROLL_SPEED;
  // Time when PSET hits the student (left side of interaction)
  const framesToImpact = (spawnX - STUDENT_LEFT_POSITION) / relativeSpeed;
  // Time when PSET enters the building zone (right side of interaction)
  const framesToEntry =
    (spawnX - (STUDENT_LEFT_POSITION + BUILDING_WIDTH + 40)) / relativeSpeed;
  const buildingDisplacement = BUILDING_SCROLL_SPEED * framesToImpact;

  // Calculate Y positions at both points in time
  const yAtImpact = spawnY + vy * framesToImpact;
  const yAtEntry = spawnY + vy * framesToEntry;

  // Determine the vertical range the projectile covers while passing the building
  const minY = Math.min(yAtImpact, yAtEntry);
  const maxY = Math.max(yAtImpact, yAtEntry);

  // Account for the projectile's height in the swept area
  const projectileTop = minY;
  const projectileBottom = maxY + PSET_SIZE;

  return buildings.some((b) => {
    const futureBx = b.x - buildingDisplacement;
    // Check if this building is the one passing the student at impact time
    if (
      STUDENT_LEFT_POSITION + STUDENT_WIDTH > futureBx &&
      STUDENT_LEFT_POSITION < futureBx + BUILDING_WIDTH
    ) {
      // Define the safe zone boundaries
      const forbiddenTop = b.gapY - FORBIDDEN_ZONE_HEIGHT / 2;
      const forbiddenBottom = b.gapY + FORBIDDEN_ZONE_HEIGHT / 2;
      // Check for overlap between projectile path and forbidden zone
      return projectileTop < forbiddenBottom && projectileBottom > forbiddenTop;
    }
    return false;
  });
};

const generateProblemSet = (
  number: number,
  currentBuildings: Building[],
  studentY: number,
): ProblemSet => {
  let x, y, vy;
  // Calculate the horizontal speed (always moving left)
  const speedX = PSET_SPEED + BUILDING_SCROLL_SPEED;
  const vx = -speedX;
  const spawnX = GAME_WIDTH + PSET_SIZE;

  const distToPlayerX = spawnX - STUDENT_LEFT_POSITION;
  // Prevent division by zero
  const timeToImpact = Math.max(0.01, distToPlayerX / speedX);
  const maxVerticalReach = PSET_MAX_VERTICAL_SPEED * timeToImpact;

  // Define the valid spawn range to avoid "way off" shots
  const minSpawnY = Math.max(0, studentY - maxVerticalReach + 50);
  const maxSpawnY = Math.min(
    GAME_HEIGHT - PSET_SIZE,
    studentY + maxVerticalReach - 50,
  );

  // Try up to 10 times to find a fair spawn position
  for (let attempt = 0; attempt < 10; attempt++) {
    x = spawnX;
    if (maxSpawnY > minSpawnY) {
      y = Math.random() * (maxSpawnY - minSpawnY) + minSpawnY;
    } else {
      y = Math.random() * (GAME_HEIGHT - 200) + 100; // Fallback
    }

    // Aim at the student with slight jitter
    const aimJitter = Math.random() * 240 - 120;
    const targetY = studentY + aimJitter;
    const requiredVy = (targetY - y) / timeToImpact;
    // Clamp speed to prevent unfair dives
    vy = Math.max(
      -PSET_MAX_VERTICAL_SPEED,
      Math.min(PSET_MAX_VERTICAL_SPEED, requiredVy),
    );

    if (!isTrajectoryBlocked(x, y, vy, currentBuildings)) {
      return {
        id: Date.now() + Math.random(),
        x,
        y,
        vx,
        vy,
        angle: 0,
        rotationSpeed: (Math.random() - 0.5) * 10,
        number,
      };
    }
  }

  // Fallback if all attempts fail
  return {
    id: Date.now() + Math.random(),
    x: GAME_WIDTH + PSET_SIZE,
    y: 50,
    vx: -speedX,
    vy: 0,
    angle: 0,
    rotationSpeed: 5,
    number,
  };
};

